<script setup>
import { inject } from 'vue';
const props = defineProps({ event: { type: Object, required: true } });
const c = inject('admin-v2');
const remove = (story,index) => c.confirmAction('Eliminare la story?', 'La story verrà rimossa dai contenuti di questo evento.', () => c.run(`stories-${props.event.id}`, () => c.deleteStory(props.event.id, story, index), 'Story eliminata.'));
</script>
<template>
 <div class="v2-stack">
  <div class="v2-toolbar"><button class="v2-button" type="button" :disabled="c.isStoriesLoading(event.id) || c.busy(`stories-${event.id}`)" @click="c.confirmAction('Ricaricare le stories?', 'Le modifiche locali delle stories saranno sostituite dai dati salvati.', () => c.run(`stories-${event.id}`, () => c.loadStoriesForEvent(event.id)))">Ricarica dati salvati</button><button class="v2-button v2-primary" type="button" :disabled="c.isStoriesSaving(event.id)" @click="c.addStoryDraft(event.id)">Aggiungi story</button><span v-if="c.isStoriesLoading(event.id)" role="status">Caricamento stories…</span></div>
  <p class="v2-muted">Pubblica video e contenuti dei giocatori. Dopo aver cambiato l’ordine salva ogni story spostata.</p>
  <p v-if="!c.isStoriesLoading(event.id) && !c.storiesForEvent(event.id).length" class="v2-empty">Nessuna story per questo evento. Aggiungi la prima.</p>
  <form v-for="(story,index) in c.storiesForEvent(event.id)" :key="story.id || `new-${index}`" class="v2-story v2-stack" @submit.prevent="c.run(`stories-${event.id}`, () => c.saveStory(event.id, story, index), 'Story salvata.')">
   <div class="v2-story-heading"><img v-if="story.thumbnail_url" class="v2-image-preview" :src="story.thumbnail_url" :alt="`Anteprima ${story.title || `story ${index + 1}`}`" /><div><h3>Story {{ index + 1 }}</h3><small>{{ story.id ? 'Contenuto salvato' : 'Nuovo contenuto da salvare' }}</small></div><span class="v2-badge" :class="story.is_active ? 'success' : ''">{{ story.is_active ? 'Attiva' : 'Nascosta' }}</span></div>
   <div class="v2-grid-2"><label class="v2-field">Nome giocatore (facoltativo)<input v-model="story.player_name" placeholder="Nome del giocatore" /></label><label class="v2-field">Titolo (facoltativo)<input v-model="story.title" placeholder="Titolo del contenuto" /></label><label class="v2-field">URL thumbnail *<input v-model="story.thumbnail_url" type="url" placeholder="https://…/anteprima.jpg" required /></label><label class="v2-field">URL video *<input v-model="story.video_url" type="url" placeholder="https://…/video.mp4" required /></label></div>
   <label class="v2-field">Oppure carica il video<input :id="`story-video-${event.id}-${index}`" type="file" accept="video/mp4,video/webm,video/quicktime" :disabled="c.isStoryVideoUploading(event.id,index) || c.isStoriesSaving(event.id)" @change="c.run(`story-upload-${event.id}-${index}`, () => c.uploadStoryVideo(event.id,story,index,$event))" /><small>{{ c.isStoryVideoUploading(event.id,index) ? 'Caricamento video in corso…' : 'Formati MP4, WebM e QuickTime. Il caricamento compila l’URL; salva poi la story.' }}</small></label>
   <div class="v2-toolbar"><label class="v2-check"><input v-model="story.is_active" type="checkbox" />Visibile ai tifosi</label><button class="v2-button" type="button" :disabled="index === 0 || c.isStoriesSaving(event.id)" @click="c.moveStory(event.id,index,-1)">Sposta su<span class="v2-sr-only"> story {{ index + 1 }}</span></button><button class="v2-button" type="button" :disabled="index === c.storiesForEvent(event.id).length - 1 || c.isStoriesSaving(event.id)" @click="c.moveStory(event.id,index,1)">Sposta giù<span class="v2-sr-only"> story {{ index + 1 }}</span></button><button class="v2-button v2-primary" :disabled="c.isStoriesSaving(event.id) || c.isStoryVideoUploading(event.id,index) || c.busy(`stories-${event.id}`)">{{ c.isStoriesSaving(event.id) ? 'Salvataggio…' : 'Salva story' }}</button><button class="v2-button v2-danger" type="button" :disabled="c.isStoriesSaving(event.id) || c.isStoryVideoUploading(event.id,index)" @click="remove(story,index)">Elimina story</button></div>
  </form>
 </div>
</template>
<style scoped>.v2-story{padding:20px;border:1px solid var(--v2-line);border-radius:10px}.v2-story-heading{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.v2-story-heading>div{flex:1;min-width:0}.v2-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:640px){.v2-story{padding:14px}.v2-story .v2-toolbar>.v2-button{flex:1}}</style>
